from __future__ import annotations

from itertools import product


def solve_coloring(instance):
    """Return True iff the graph is 3-colourable."""
    n = instance["n"]
    edges = instance["edges"]
    for colouring in product(range(3), repeat=n):
        if all(colouring[u] != colouring[v] for u, v in edges):
            return True
    return False


def _simplify(clauses, var, value):
    """Apply var=value, return simplified clause list or None if conflict."""
    result = []
    for clause in clauses:
        if (var if value else -var) in clause:
            continue  # clause satisfied
        new_clause = [lit for lit in clause if lit != (-var if value else var)]
        if not new_clause:
            return None  # empty clause -> conflict
        result.append(new_clause)
    return result


def _dpll(clauses):
    # Unit propagation.
    while True:
        unit = None
        for clause in clauses:
            if len(clause) == 1:
                unit = clause[0]
                break
        if unit is None:
            break
        clauses = _simplify(clauses, abs(unit), unit > 0)
        if clauses is None:
            return False

    if not clauses:
        return True  # all clauses satisfied

    # Choose the variable appearing most often.
    counts = {}
    for clause in clauses:
        for lit in clause:
            counts[abs(lit)] = counts.get(abs(lit), 0) + 1
    var = max(counts, key=counts.get)

    for value in (True, False):
        reduced = _simplify(clauses, var, value)
        if reduced is not None and _dpll(reduced):
            return True
    return False


def solve_sat(instance):
    """Return True iff the 3-SAT formula is satisfiable."""
    m = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]
    if m == 0:
        return not clauses
    return _dpll(clauses)
